const fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),origin='https://4050guide.co.kr',route='/재취업-직무-비교/';
const rows=require('./career-comparison-20261104.cjs'),evidence=require('../assets/comparison-evidence-20261030.json'),photos=require('../assets/catalog-photo-map.json');
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const sources=rows.map(r=>evidence.jobs.find(j=>j.id===r.sourceId));if(sources.some(s=>!s))throw Error('Missing job evidence');
const title='시설관리·돌봄·조리·물류 직무 비교 - 4050가이드',description='40·50대 비전공자를 위한 네 직무의 채용조건 비교. 야간근무, 자차 출퇴근과 교육비 제약에 맞춰 공고에서 확인할 질문을 정리합니다.';
const photoRow=rows.map(r=>{const p=photos[r.article];if(!p)throw Error('Missing photo');return `<a href="#row-${r.id}"><img src="${esc(p.image)}" srcset="${esc(p.srcset)}" sizes="(max-width:700px) 44vw, 260px" width="800" height="500" alt="${esc(p.alt)}" decoding="async"><span>${r.name}</span></a>`}).join('');
const tableRows=rows.map((r,i)=>`<tr id="row-${r.id}"><th scope="row"><a href="/${r.article}/">${r.name}</a></th><td>${r.entry}</td><td>${r.schedule}<p class="compare-pay">표본 표시임금: ${esc(sources[i].pay)}</p></td><td>${r.burden}</td><td>${r.cost}</td><td><a href="${esc(sources[i].url)}" target="_blank" rel="noopener noreferrer">공식 공고 ${r.sourceId}</a><br><a href="/${r.prep}/">자격 준비</a></td></tr>`).join('');
const notes=rows.map(r=>`<li data-result="${r.id}"><h3>${r.name}</h3><ul><li>${r.base}</li></ul><a href="/${r.article}/">공고 해석과 비교 사례 <span aria-hidden="true">→</span></a></li>`).join('');
const main=`<main class="catalog-main compare-main" data-career-comparison><div class="wrap">
 <nav class="compare-breadcrumb" aria-label="현재 위치"><a href="/">홈</a><span aria-hidden="true">/</span><span>직무 비교</span></nav>
 <header class="compare-intro"><p class="catalog-kicker">40·50대 비전공자의 첫 재취업 준비</p><h1>시설관리·돌봄·조리·물류 직무 비교</h1><p>자격증 이름보다 신입 지원 여부와 근무표부터 비교합니다. 아래 네 공고는 직무의 평균이나 현재 채용목록이 아니라, 조건을 읽는 법을 익히는 개별 사례입니다.</p><div class="compare-entry-links"><a href="#my-conditions">내 조건부터 확인 <span aria-hidden="true">↓</span></a><a href="/assets/worksheets/career-comparison-20261104.csv" download><span aria-hidden="true">↓</span> 공고 비교 기록표</a></div></header>
 <div class="compare-photo-row">${photoRow}</div>
 <section class="compare-table-section" aria-labelledby="compare-table-heading"><h2 id="compare-table-heading">네 직무를 같은 항목으로 비교하세요</h2><p class="compare-evidence-note">자료 기준: 2026년 10월 30일 공고 정리. 주간·교대, 신입·경력 조건은 같은 직무 안에서도 달라집니다. 표시임금은 실수령액이나 동일 시간의 임금 비교가 아닙니다.</p>
 <div class="compare-scroll" role="region" aria-label="네 직무 채용조건 비교표" tabindex="0"><table><caption class="catalog-sr">개별 공고 표본 네 건의 지원조건·시간·확인 질문·비용 준비 비교</caption><thead><tr><th scope="col">직무</th><th scope="col">신입·자격 조건</th><th scope="col">근무표·표시임금</th><th scope="col">현장 부담 질문</th><th scope="col">비용을 쓰기 전</th><th scope="col">비교 근거</th></tr></thead><tbody>${tableRows}</tbody></table></div></section>
 <section class="compare-conditions" id="my-conditions" aria-labelledby="my-conditions-heading"><h2 id="my-conditions-heading">내가 어려운 조건부터 대조해 보세요</h2><p>직무를 탈락시키거나 적합도를 매기지 않습니다. 선택한 제약에 따라 공고와 채용처에서 확인할 질문을 정리합니다.</p><form id="compare-conditions"><fieldset disabled><legend>내가 피하거나 먼저 확인해야 하는 조건</legend><label><input type="checkbox" name="constraint" value="night"> 야간근무가 어렵다</label><label><input type="checkbox" name="constraint" value="commute"> 자차 출퇴근이 어렵다</label><label><input type="checkbox" name="constraint" value="cost"> 교육비가 부담된다</label></fieldset><button type="reset" title="조건 선택 초기화" aria-label="조건 선택 초기화"><span aria-hidden="true">↺</span></button></form><p id="compare-status" role="status">직무별로 먼저 확인할 내용입니다.</p><ul class="compare-results">${notes}</ul><noscript><p>위 비교표와 직무별 질문은 자바스크립트 없이도 읽을 수 있습니다. 공고 비교 기록표에 내 조건을 적어 대조하세요.</p></noscript><p class="compare-evidence-note">조건 선택은 브라우저 메모리에서만 처리하며 저장하거나 서버로 보내지 않습니다.</p></section>
 <section class="compare-example" aria-labelledby="compare-example-heading"><h2 id="compare-example-heading">야간도 자차 출퇴근도 어렵다면</h2><p>조리원 표본은 야간 교대가 없어도 새벽 05시 출근·자차 조건 때문에 맞지 않을 수 있습니다. 지게차 표본은 야간과 경력 요건이 있고, 요양원 표본은 야간과 출근차량의 이용 조건을 확인해야 합니다. 시설관리 표본도 07시 출근과 실제 근무일을 대조해야 합니다.</p><p>이 사례만으로 네 직무 모두를 포기할 이유는 없습니다. 기록표에 가능한 출근시각과 이동수단을 먼저 적고, 같은 직무의 다른 공고에서 <strong>일정과 경력 요건이 모두 맞는지</strong> 확인하는 것이 다음 행동입니다.</p><p><a href="/assets/worksheets/career-comparison-20261104.csv" download>공고 비교 기록표 내려받기</a> · <a href="/4050-자격증-로드맵/">일자리에서 자격증·훈련비까지 준비하는 순서</a></p></section>
 <details class="compare-sources"><summary>공식 자료와 비교 범위</summary><p>작성: 2026년 11월 4일. 임금·시간·요건은 10월 30일 정리한 개별 공고의 표기이며, 직접 근무·지원·전화 확인한 결과가 아닙니다. 교육기간과 수강료는 이 표본만으로 정할 수 없어 직무별 평균 비용을 만들지 않았습니다. 현장 부담 항목과 조건별 질문은 편집자가 만든 확인 질문입니다.</p><ul>${sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${s.id} ${esc(s.name)}</a> — ${esc(s.status)}</li>`).join('')}</ul><p>11월 4일 자료 재조회에서 시설관리·요양·지게차의 본문을 확인했으나 현재 모집 여부를 판정하지 않았습니다. 조리원 J10 원문은 재열람되지 않아 기존 정리 자료만 사용했습니다. 원문이 바뀌거나 열리지 않으면 이 수치를 현재 채용조건으로 사용하지 말고 새로운 공고를 확인하세요.</p><p><a href="/정보-출처-및-면책-안내/">출처·편집·수정 기준</a></p></details>
 </div></main>`;
let html=fs.readFileSync(path.join(root,'index.html'),'utf8').replace(/<main\b[\s\S]*?<\/main>/,main).replace(/<title>[\s\S]*?<\/title>/,'<title>'+title+'</title>');
html=html.replace(/<script\b[^>]*src="\/assets\/(?:catalog|home-ads)\.js[^\"]*"[^>]*><\/script>\s*/g,'');
html=html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,block=>/id="wp-emoji-settings"|sourceURL=.*wp-emoji-loader\.min\.js/.test(block)?'':block);
html=html.replace(/(<link\b[^>]*rel="canonical"[^>]*href=")[^"]*/,'$1'+origin+route).replace(/(<meta (?:property="og:url") content=")[^"]*/g,'$1'+origin+route);
html=html.replace(/(<meta (?:name="description"|property="og:description"|name="twitter:description") content=")[^"]*/g,'$1'+esc(description)).replace(/(<meta (?:property="og:title"|name="twitter:title") content=")[^"]*/g,'$1'+esc(title));
html=html.replace(/<script\b[^>]*type="application\/ld\+json"[^>]*>[\s\S]*?<\/script>/g,'<script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org','@type':'WebPage',name:title,url:origin+route,description,inLanguage:'ko-KR',dateModified:'2026-11-04',isPartOf:{'@type':'WebSite',name:'4050가이드',url:origin+'/'}})+'</script>');
html=html.replace('</head>','<link rel="stylesheet" href="/assets/career-compare.css?v=20261104">\n<script defer src="/assets/career-compare.js?v=20261104"></script>\n</head>');
html=html.replace('</body>','<script type="application/json" id="career-condition-data">'+JSON.stringify(rows.map(({id,name,base,notes})=>({id,name,base,notes}))).replaceAll('<','\\u003c')+'</script>\n</body>');
const dir=path.join(root,decodeURI(route));fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),html);
const columns=['직무','공고 확인일','공고 URL','경력·자격 표기','근무시간 표기','표시임금','내가 가능한 출근시각','야간 가능 여부','이동수단','직무·신체 부담 확인 질문','본인부담 교육비','재료·실습비','통학비','응시·발급비','공고에 추가 확인할 내용'];
const csvRows=rows.map((r,i)=>[r.name,'2026-10-30',sources[i].url,r.entry,r.schedule,sources[i].pay,'','','',r.burden,'','','','','과거 표본; 현재 모집·조건 재확인']);csvRows.push(Array(columns.length).fill(''),Array(columns.length).fill(''));
fs.writeFileSync(path.join(root,'assets/worksheets/career-comparison-20261104.csv'),'\uFEFF'+[columns,...csvRows].map(row=>row.map(value=>'"'+String(value).replaceAll('"','""')+'"').join(',')).join('\r\n')+'\r\n');
async function finish(){const browser=await chromium.launch();try{const p=await browser.newPage();
 const resources=await p.evaluate(html=>{const d=new DOMParser().parseFromString(html,'text/html');return [...d.querySelectorAll('[href],[src]')].flatMap(n=>['href','src'].map(name=>{const value=n.getAttribute(name);if(!value||value.startsWith('/')||value.startsWith('#')||/^[a-z][a-z0-9+.-]*:/i.test(value))return null;const u=new URL(value,'https://4050guide.co.kr/');return {name,from:value,to:u.pathname+u.search+u.hash};}).filter(Boolean));},html);
 for(const r of resources)for(const quote of ['"',"'"])html=html.replaceAll(r.name+'='+quote+r.from+quote,r.name+'='+quote+r.to+quote);
 fs.writeFileSync(path.join(dir,'index.html'),html);
 const xml=await p.evaluate(({xml,loc})=>{const d=new DOMParser().parseFromString(xml,'application/xml'),ns=d.documentElement.namespaceURI;let u=[...d.getElementsByTagName('url')].find(n=>n.getElementsByTagName('loc')[0]?.textContent===loc);if(!u){u=d.createElementNS(ns,'url');const l=d.createElementNS(ns,'loc');l.textContent=loc;u.append(l);d.documentElement.append(u)}let m=u.getElementsByTagName('lastmod')[0];if(!m){m=d.createElementNS(ns,'lastmod');u.append(m)}m.textContent='2026-11-04';return new XMLSerializer().serializeToString(d)},{xml:fs.readFileSync(path.join(root,'sitemap.xml'),'utf8'),loc:origin+route});fs.writeFileSync(path.join(root,'sitemap.xml'),xml+'\n');console.log('Built career comparison and CSV worksheet');}finally{await browser.close()}}
finish().catch(e=>{console.error(e);process.exitCode=1});
